        var details = lines.Select(l => new
        {
            l.Id,
            l.Vin,
            l.Model,
            l.SpecCode,
            l.Color,
            l.UnitPrice,
            l.Discount,
            l.ActualPrice,
            l.Status,
            l.Remark,
            vehicle = vehicles.TryGetValue(l.Vin, out var v) ? new
            {
                v.EngineNo,
                v.ModelYear,
                v.StorageCode,
                v.DealerCode,
                status = v.Status.ToString(),
