            l.Vin,
            l.Model,
            l.SpecCode,
            l.OldColor,
            l.NewColor,
            l.OldColorCode,
            l.NewColorCode,
            l.OldColorName,
            l.NewColorName,
            l.Status,
            l.Remark,
            vehicle = vehicles.TryGetValue(l.Vin, out var v) ? new
            {
                v.EngineNo,
                v.Color,
