            var laborAmount = item.LaborAmount ?? Math.Max(0, (stdHours * laborPrice) - discount);
            newLines.Add(new ServiceAppointmentServiceLine
            {
                OrgId = Org,
                ServiceAppointmentId = app.Id,
                AppNo = app.AppNo,
                SerCode = item.SerCode.Trim(),
