        var completedCount = lines.Count(l => l.Status == "Completed");
        var completionPercent = lines.Count > 0 ? Math.Round((decimal)completedCount / lines.Count * 100, 1) : 0;

        return new
        {
            b.Id,
            b.BulletinNo,
            b.BulletinNoUser,
            b.Title,
            b.Category,
            b.Model,
            b.Severity,
            b.ReleaseDate,
            b.ExpiryDate,
            b.Description,
            b.Remedy,
            b.AttachmentFileName,
            b.AttachmentUrl,
            totalVehicleCount = lines.Count,
            completedVehicleCount = completedCount,
            pendingVehicleCount = lines.Count - completedCount,
            completionPercent,
            b.Status,
            b.Remark,
            b.CreatedBy,
            b.CreatedAt,
            b.PublishedBy,
            b.PublishedAt,
            b.ArchivedBy,
            b.ArchivedAt,
            b.CancelledBy,
            b.CancelledAt,
            b.CancelReason,
            Lines = lines.Select(l => new
            {
                l.Id,
