            .ToDictionaryAsync(b => b.Id);

        return new
        {
            vin = v.Vin,
            model = v.Model,
            plateNo = v.PlateNo,
            dealerCode = v.DealerCode,
            lastBulletinNo = v.LastBulletinNo,
            lastBulletinDate = v.LastBulletinDate,
