    public async Task<object?> GetVehicleQuotationHistoryAsync(string vin)
    {
        vin = vin.Trim().ToUpperInvariant();
        var v = await db.Vehicles.FirstOrDefaultAsync(x => x.OrgId == Org && x.Vin == vin);
        if (v is null) return null;

        var quotes = await db.ServiceQuotations
            .Where(q => q.OrgId == Org && q.Vin == vin)
            .OrderByDescending(q => q.QuoteDate)
            .ToListAsync();

        var quoteIds = quotes.Select(q => q.Id).ToList();
        var laborCounts = await db.ServiceQuotationLaborLines
            .Where(l => l.OrgId == Org && quoteIds.Contains(l.ServiceQuotationId))
            .GroupBy(l => l.ServiceQuotationId)
            .ToDictionaryAsync(g => g.Key, g => g.Count());

        var partCounts = await db.ServiceQuotationPartLines
            .Where(p => p.OrgId == Org && quoteIds.Contains(p.ServiceQuotationId))
            .GroupBy(p => p.ServiceQuotationId)
            .ToDictionaryAsync(g => g.Key, g => g.Count());

        var items = quotes.Select(q => new
        {
            q.QuoteNo,
            q.QuoteNoUser,
            q.DealerCode,
            q.DealerName,
            q.OdoKm,
            q.CustomerName,
            q.CustomerPhone,
            q.QuotationType,
            q.ServiceAdvisor,
            q.QuoteDate,
            q.ValidUntilDate,
            q.PaymentMethod,
            q.TotalLaborAmount,
            q.TotalPartAmount,
            q.DiscountAmount,
            q.TotalVatAmount,
            q.TotalAmount,
            q.Status,
            q.ApprovedByCustomer,
            q.CustomerApprovedAt,
            q.ConvertedRoNo,
            q.ConvertedAt,
            laborLineCount = laborCounts.GetValueOrDefault(q.Id, 0),
            partLineCount = partCounts.GetValueOrDefault(q.Id, 0)
        }).ToList();

        return new
        {
            vin = v.Vin,
            model = v.Model,
            plateNo = v.PlateNo,
            ownerName = v.OwnerName,
            v.LastQuoteNo,
            v.LastQuoteDate,
            totalQuotations = items.Count,
            totalEstimatedAmount = items.Sum(x => x.TotalAmount),
            convertedToRoCount = items.Count(x => x.Status == "Converted"),
            quotations = items
        };
    }

    public async Task<object> GetQuotationSummaryAsync(string? dealerCode, DateTime? fromDate, DateTime? toDate)
    {
        var q = db.ServiceQuotations.Where(x => x.OrgId == Org);
        if (!string.IsNullOrWhiteSpace(dealerCode)) q = q.Where(x => x.DealerCode == dealerCode);
        if (fromDate.HasValue) q = q.Where(x => x.QuoteDate >= fromDate.Value);
        if (toDate.HasValue) q = q.Where(x => x.QuoteDate <= toDate.Value);

        var quotes = await q.ToListAsync();

        var totalQuotes = quotes.Count;
        var draftCount = quotes.Count(x => x.Status == "Draft");
        var sentCount = quotes.Count(x => x.Status == "Sent");
        var approvedCount = quotes.Count(x => x.Status == "CustomerApproved");
        var convertedCount = quotes.Count(x => x.Status == "Converted");
        var rejectedCount = quotes.Count(x => x.Status == "CustomerRejected");
        var cancelledCount = quotes.Count(x => x.Status == "Cancelled");

        var totalLaborAmount = quotes.Sum(x => x.TotalLaborAmount);
        var totalPartAmount = quotes.Sum(x => x.TotalPartAmount);
        var totalQuotationAmount = quotes.Sum(x => x.TotalAmount);
        var convertedAmount = quotes.Where(x => x.Status == "Converted").Sum(x => x.TotalAmount);

        var conversionRatePercent = totalQuotes > 0 ? Math.Round((double)convertedCount / totalQuotes * 100, 1) : 0;
        var customerApprovalRatePercent = totalQuotes > 0 ? Math.Round((double)(approvedCount + convertedCount) / totalQuotes * 100, 1) : 0;

        var byType = quotes.GroupBy(x => x.QuotationType).Select(g => new
        {
            quotationType = g.Key,
            count = g.Count(),
            convertedCount = g.Count(x => x.Status == "Converted"),
            totalAmount = g.Sum(x => x.TotalAmount),
            convertedAmount = g.Where(x => x.Status == "Converted").Sum(x => x.TotalAmount)
        }).ToList();

        var byDealer = quotes.GroupBy(x => x.DealerCode).Select(g => new
        {
            dealerCode = g.Key,
            count = g.Count(),
            convertedCount = g.Count(x => x.Status == "Converted"),
            totalAmount = g.Sum(x => x.TotalAmount),
            convertedAmount = g.Where(x => x.Status == "Converted").Sum(x => x.TotalAmount)
        }).ToList();

        return new
        {
            totalQuotes,
            draftCount,
            sentCount,
            approvedCount,
            convertedCount,
            rejectedCount,
            cancelledCount,
            conversionRatePercent,
            customerApprovalRatePercent,
            totalLaborAmount,
            totalPartAmount,
            totalQuotationAmount,
            convertedAmount,
            byType,
            byDealer
        };
    }

    // ===== Chăm sóc khách hàng & Khảo sát CSI sau dịch vụ/bán xe (BizCarSv.Customer / Ser_CustomerCare) =====
    public async Task<object> CreateCustomerCareAsync(CreateCustomerCareDto dto)
    {
        if (string.IsNullOrWhiteSpace(dto.Vin))
            throw new InvalidOperationException("Cần cung cấp số khung VIN để lập phiếu chăm sóc khách hàng.");

        var vin = dto.Vin.Trim().ToUpperInvariant();
        var vehicle = await db.Vehicles.FirstOrDefaultAsync(v => v.OrgId == Org && v.Vin == vin);
        if (vehicle == null)
            throw new InvalidOperationException($"Không tìm thấy xe với số khung {vin}.");

        var careNo = string.IsNullOrWhiteSpace(dto.CareNo)
            ? "CC" + DateTime.Now.ToString("yyMMddHHmmss")
            : dto.CareNo.Trim().ToUpperInvariant();

        if (await db.CustomerCares.AnyAsync(x => x.OrgId == Org && x.CareNo == careNo))
            throw new InvalidOperationException($"Mã phiếu CSKH {careNo} đã tồn tại.");

        var dealerCode = !string.IsNullOrWhiteSpace(dto.DealerCode) ? dto.DealerCode.Trim().ToUpperInvariant() : (vehicle.DealerCode ?? "DLR-HN01");
        var dealerName = dto.DealerName?.Trim() ?? (dealerCode == "DLR-HN01" ? "Hyundai Hà Nội 01" : dealerCode == "DLR-HP01" ? "Hyundai Hải Phòng" : "Đại lý Ủy quyền Hyundai");

        var careType = !string.IsNullOrWhiteSpace(dto.CareType) ? dto.CareType.Trim() : "FollowUp72h";
        var contactMethod = !string.IsNullOrWhiteSpace(dto.ContactMethod) ? dto.ContactMethod.Trim() : "PhoneCall";
        var customerName = !string.IsNullOrWhiteSpace(dto.CustomerName) ? dto.CustomerName.Trim() : (vehicle.OwnerName ?? "Khách hàng");
        var customerPhone = !string.IsNullOrWhiteSpace(dto.CustomerPhone) ? dto.CustomerPhone.Trim() : (vehicle.OwnerPhone ?? "");
        var plateNo = !string.IsNullOrWhiteSpace(dto.PlateNo) ? dto.PlateNo.Trim() : (vehicle.PlateNo ?? "");
        var model = !string.IsNullOrWhiteSpace(dto.Model) ? dto.Model.Trim() : vehicle.Model;
        var engineNo = !string.IsNullOrWhiteSpace(dto.EngineNo) ? dto.EngineNo.Trim() : vehicle.EngineNo;
        var odoKm = dto.OdoKm ?? vehicle.LastOdoKm ?? 0;

        var care = new CustomerCare
        {
            OrgId = Org,
            CareNo = careNo,
            CareNoUser = dto.CareNoUser?.Trim(),
            DealerCode = dealerCode,
            DealerName = dealerName,
            Vin = vin,
            PlateNo = plateNo,
            Model = model,
            EngineNo = engineNo,
            CustomerName = customerName,
            CustomerPhone = customerPhone,
            CustomerEmail = dto.CustomerEmail?.Trim(),
            CustomerAddress = dto.CustomerAddress?.Trim(),
            CareType = careType,
            ContactMethod = contactMethod,
            RoNo = dto.RoNo?.Trim().ToUpperInvariant() ?? vehicle.LastRoNo,
            DoNo = dto.DoNo?.Trim().ToUpperInvariant(),
            OdoKm = odoKm,
            ServiceDate = dto.ServiceDate ?? vehicle.LastRoDate ?? vehicle.DeliveredAt ?? DateTime.Now.AddDays(-3),
            ContactDate = dto.ContactDate,
            NextCareDate = dto.NextCareDate,
            CallAttempts = Math.Max(1, dto.CallAttempts),
            CareStaff = dto.CareStaff?.Trim(),
            ServiceAdvisor = dto.ServiceAdvisor?.Trim(),
            ScoreOverall = Math.Clamp(dto.ScoreOverall, 1.0m, 5.0m),
            ScoreQuality = Math.Clamp(dto.ScoreQuality, 1.0m, 5.0m),
            ScoreAdvisor = Math.Clamp(dto.ScoreAdvisor, 1.0m, 5.0m),
            ScoreFacility = Math.Clamp(dto.ScoreFacility, 1.0m, 5.0m),
            IsProblemSolved = dto.IsProblemSolved,
            NpsScore = Math.Clamp(dto.NpsScore, 0, 10),
            CustomerFeedback = dto.CustomerFeedback?.Trim(),
            RemedyAction = dto.RemedyAction?.Trim(),
            IsResolved = true,
            Status = "Pending",
            Remark = dto.Remark?.Trim(),
            CreatedBy = dto.CreatedBy?.Trim(),
            CreatedAt = DateTime.Now
        };

        db.CustomerCares.Add(care);
        Log(vin, "CustomerCareCreated", $"{careNo} Lập phiếu chăm sóc khách hàng loại {careType} ({contactMethod}). Khách hàng: {customerName}");
        await db.SaveChangesAsync();

        return new
        {
            care.CareNo,
            care.CareNoUser,
            care.DealerCode,
            care.DealerName,
            care.Vin,
            care.PlateNo,
            care.Model,
            care.CustomerName,
            care.CustomerPhone,
            care.CareType,
            care.ContactMethod,
            care.RoNo,
            care.OdoKm,
            care.Status,
            care.CreatedAt
        };
    }

    public async Task<object> ListCustomerCaresAsync(string? status, string? dealer, string? vin, string? careType, string? contactMethod, decimal? minScore, string? careNo)
    {
        var q = db.CustomerCares.Where(x => x.OrgId == Org);

        if (!string.IsNullOrWhiteSpace(status))
        {
            var st = status.Trim().ToLowerInvariant();
            q = q.Where(x => x.Status.ToLower() == st);
        }
        if (!string.IsNullOrWhiteSpace(dealer))
        {
            var d = dealer.Trim().ToUpperInvariant();
            q = q.Where(x => x.DealerCode.ToUpper() == d);
        }
        if (!string.IsNullOrWhiteSpace(vin))
        {
            var v = vin.Trim().ToUpperInvariant();
            q = q.Where(x => x.Vin.ToUpper().Contains(v));
        }
        if (!string.IsNullOrWhiteSpace(careType))
        {
            var ct = careType.Trim().ToLowerInvariant();
            q = q.Where(x => x.CareType.ToLower() == ct);
        }
        if (!string.IsNullOrWhiteSpace(contactMethod))
        {
            var cm = contactMethod.Trim().ToLowerInvariant();
            q = q.Where(x => x.ContactMethod.ToLower() == cm);
        }
        if (minScore.HasValue)
        {
            q = q.Where(x => x.ScoreOverall >= minScore.Value);
        }
        if (!string.IsNullOrWhiteSpace(careNo))
        {
            var cn = careNo.Trim().ToUpperInvariant();
            q = q.Where(x => x.CareNo.Contains(cn) || (x.CareNoUser != null && x.CareNoUser.Contains(cn)));
        }

        var items = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new
        {
            x.Id,
            x.CareNo,
            x.CareNoUser,
            x.DealerCode,
            x.DealerName,
            x.Vin,
            x.PlateNo,
            x.Model,
            x.CustomerName,
            x.CustomerPhone,
            x.CustomerEmail,
            x.CareType,
            x.ContactMethod,
            x.RoNo,
            x.DoNo,
            x.OdoKm,
            x.ServiceDate,
            x.ContactDate,
            x.NextCareDate,
            x.CallAttempts,
            x.CareStaff,
            x.ServiceAdvisor,
            x.ScoreOverall,
            x.ScoreQuality,
            x.ScoreAdvisor,
            x.ScoreFacility,
            x.IsProblemSolved,
            x.NpsScore,
            x.CustomerFeedback,
            x.RemedyAction,
            x.IsResolved,
            x.Status,
            x.EscalatedTo,
            x.EscalatedAt,
            x.CompletedBy,
            x.CompletedAt,
            x.CancelledBy,
            x.CancelledAt,
            x.CancelReason,
            x.Remark,
            x.CreatedBy,
            x.CreatedAt
        }).ToListAsync();

        return new { count = items.Count, items };
    }

    public async Task<object?> GetCustomerCareAsync(string careNo)
    {
