            p.TotalBeforeVAT,
            p.VatRate,
            p.TotalVatAmount,
            p.TotalAmount,
            p.Status,
            p.TransporterSignStatus,
            p.TransporterSignDate,
            p.TransporterSignBy,
            p.HTVSignStatus,
            p.HTVSignDate,
            p.HTVSignBy,
            p.BankRefNo,
            p.PaymentDate,
            p.FilePath,
            p.Remark,
            p.CreatedBy,
            p.CreatedAt,
            p.Approved1By,
            p.Approved1At,
            p.Approved2By,
