            p.SettledBy,
            p.SettledAt,
            p.RejectedBy,
            p.RejectedAt,
            p.RejectReason,
            p.CancelledBy,
            p.CancelledAt,
            p.CancelReason,
            items = lines.Select(l => new
            {
