    public async Task<object?> StaffCertificateTransitionAsync(string certNo, string action, StaffCertificateTransitionDto? dto)
    {
        certNo = certNo.Trim().ToUpperInvariant();
        var cert = await db.StaffCertificates.FirstOrDefaultAsync(c => c.OrgId == Org && (c.CertificateNo == certNo || c.CertificateNoUser == certNo));
        if (cert is null) return null;

        var actor = dto?.Actor?.Trim() ?? "Admin";
        var now = dto?.TransitionDate ?? DateTime.Now;

        switch (action.Trim().ToLowerInvariant())
        {
            case "activate":
                cert.Status = "Active";
                cert.UpdatedAt = now;
                break;

            case "renew":
                cert.Status = "Active";
                cert.ExpiryDate = dto?.ExpiryDate ?? cert.ExpiryDate.AddYears(2);
                cert.Remark = (cert.Remark != null ? cert.Remark + "; " : "") + $"Gia hạn hiệu lực chứng chỉ đến {cert.ExpiryDate:dd/MM/yyyy} bởi {actor}";
                cert.UpdatedAt = now;
                break;

            case "suspend":
                if (cert.Status != "Active")
                    throw new InvalidOperationException($"Chỉ có thể tạm đình chỉ chứng chỉ đang Active. Hiện tại là {cert.Status}.");
                cert.Status = "Suspended";
                cert.Remark = (cert.Remark != null ? cert.Remark + "; " : "") + $"Tạm đình chỉ bởi {actor}: {dto?.Reason ?? dto?.Note ?? "N/A"}";
                cert.UpdatedAt = now;
                break;

            case "expire":
                cert.Status = "Expired";
                cert.UpdatedAt = now;
                break;

            case "revoke":
                if (cert.Status == "Revoked")
                    throw new InvalidOperationException("Chứng chỉ này đã bị thu hồi trước đó.");
                cert.Status = "Revoked";
                cert.RevokedBy = actor;
                cert.RevokedAt = now;
                cert.RevokeReason = dto?.Reason?.Trim() ?? dto?.Note?.Trim() ?? "Thu hồi do vi phạm quy chế đại lý";
                cert.UpdatedAt = now;
                break;

            default:
                throw new InvalidOperationException($"Hành động không hợp lệ: {action}");
        }

        await db.SaveChangesAsync();
        return cert;
    }

    public async Task<object?> GetDealerTrainingMatrixAsync(string? dealerCode)
    {
        var qCert = db.StaffCertificates.Where(c => c.OrgId == Org);
        var qEnr = db.TrainingEnrollments.Where(e => e.OrgId == Org);

        if (!string.IsNullOrWhiteSpace(dealerCode))
        {
            var d = dealerCode.Trim().ToUpperInvariant();
            qCert = qCert.Where(c => c.DealerCode == d);
            qEnr = qEnr.Where(e => e.DealerCode == d);
        }

        var certificates = await qCert.ToListAsync();
        var enrollments = await qEnr.ToListAsync();

        var dealerGroup = certificates.GroupBy(c => c.DealerCode).ToList();
        var targetDealer = !string.IsNullOrWhiteSpace(dealerCode) ? dealerCode.Trim().ToUpperInvariant() : (dealerGroup.FirstOrDefault()?.Key ?? "DLR-HN01");
        var dealerName = certificates.FirstOrDefault(c => c.DealerCode == targetDealer)?.DealerName ?? enrollments.FirstOrDefault(e => e.DealerCode == targetDealer)?.DealerName ?? targetDealer;

        var dealerCerts = certificates.Where(c => c.DealerCode == targetDealer).ToList();
        var dealerEnrs = enrollments.Where(e => e.DealerCode == targetDealer).ToList();

        // Nhóm theo nhân sự của đại lý
        var allStaffCodes = dealerCerts.Select(c => c.StaffCode).Union(dealerEnrs.Select(e => e.StaffCode)).Distinct().ToList();

        var staffItems = new List<DealerStaffTrainingItemDto>();
        foreach (var sc in allStaffCodes)
        {
            var sCerts = dealerCerts.Where(c => c.StaffCode == sc).OrderByDescending(c => c.IssueDate).ToList();
            var sEnrs = dealerEnrs.Where(e => e.StaffCode == sc).ToList();
            var activeCert = sCerts.FirstOrDefault(c => c.Status == "Active" && c.ExpiryDate >= DateTime.Now);

            var sName = activeCert?.StaffName ?? sCerts.FirstOrDefault()?.StaffName ?? sEnrs.FirstOrDefault()?.StaffName ?? sc;
            var pos = activeCert?.Position ?? sCerts.FirstOrDefault()?.Position ?? sEnrs.FirstOrDefault()?.Position ?? "Staff";

            var attendedCount = sEnrs.Count;
            var passedCount = sEnrs.Count(e => e.ResultStatus == "Passed");
            var avgScore = sEnrs.Count > 0 ? Math.Round(sEnrs.Average(e => e.FinalScore), 1) : (activeCert?.ScoreAchieved ?? 0m);

            staffItems.Add(new DealerStaffTrainingItemDto(
                sc,
                sName,
                pos,
                activeCert != null,
                activeCert?.CertificateNo,
                activeCert?.CertificateType,
                activeCert?.Level,
                activeCert?.ExpiryDate,
                attendedCount,
                passedCount,
                avgScore
            ));
        }

        var totalStaff = staffItems.Count;
        var certifiedSales = staffItems.Count(s => s.IsCertified && (s.CertificateType == "SalesConsultant" || s.Position.Contains("Sales") || s.Position.Contains("TVBH")));
        var certifiedAdvisor = staffItems.Count(s => s.IsCertified && (s.CertificateType == "ServiceAdvisor" || s.Position.Contains("Advisor") || s.Position.Contains("CVDV")));
        var certifiedTech = staffItems.Count(s => s.IsCertified && (s.CertificateType == "MasterTechnician" || s.Position.Contains("Technician") || s.Position.Contains("KTV")));
        var certifiedEV = staffItems.Count(s => s.IsCertified && (s.CertificateType == "EVTechnician" || s.Position.Contains("EV")));
        var totalActive = staffItems.Count(s => s.IsCertified);
        var stdScore = totalStaff > 0 ? Math.Round((decimal)totalActive / totalStaff * 100, 1) : 0m;

        return new DealerTrainingMatrixDto(
            targetDealer,
            dealerName,
            totalStaff,
            certifiedSales,
            certifiedAdvisor,
            certifiedTech,
            certifiedEV,
            totalActive,
            stdScore,
            staffItems
        );
    }

    public async Task<object?> GetStaffTrainingProfileAsync(string staffCode)
    {
        staffCode = staffCode.Trim().ToUpperInvariant();

        var certs = await db.StaffCertificates
            .Where(c => c.OrgId == Org && c.StaffCode == staffCode)
            .OrderByDescending(c => c.IssueDate)
            .ToListAsync();

        var enrollments = await db.TrainingEnrollments
            .Where(e => e.OrgId == Org && e.StaffCode == staffCode)
            .OrderByDescending(e => e.Id)
            .ToListAsync();

        if (certs.Count == 0 && enrollments.Count == 0) return null;

        var activeCert = certs.FirstOrDefault(c => c.Status == "Active" && c.ExpiryDate >= DateTime.Now);
        var staffName = activeCert?.StaffName ?? certs.FirstOrDefault()?.StaffName ?? enrollments.FirstOrDefault()?.StaffName ?? staffCode;
        var dealerCode = activeCert?.DealerCode ?? certs.FirstOrDefault()?.DealerCode ?? enrollments.FirstOrDefault()?.DealerCode ?? "";
        var dealerName = activeCert?.DealerName ?? certs.FirstOrDefault()?.DealerName ?? enrollments.FirstOrDefault()?.DealerName ?? dealerCode;
        var pos = activeCert?.Position ?? certs.FirstOrDefault()?.Position ?? enrollments.FirstOrDefault()?.Position ?? "Staff";
        var email = activeCert?.StaffEmail ?? certs.FirstOrDefault()?.StaffEmail ?? enrollments.FirstOrDefault()?.StaffEmail;
        var phone = activeCert?.StaffPhone ?? certs.FirstOrDefault()?.StaffPhone ?? enrollments.FirstOrDefault()?.StaffPhone;

        var tCodes = enrollments.Select(e => e.TrainingCode).Distinct().ToList();
        var courses = await db.TrainingCourses.Where(c => c.OrgId == Org && tCodes.Contains(c.TrainingCode)).ToDictionaryAsync(c => c.TrainingCode);

        var history = enrollments.Select(e =>
        {
            courses.TryGetValue(e.TrainingCode, out var c);
            return new StaffEnrollmentHistoryDto(
                e.EnrollmentNo,
                e.TrainingCode,
                c?.CourseName ?? e.TrainingCode,
                c?.TrainingType ?? "SalesConsultant",
                c?.Level ?? "Intermediate",
                c?.StartDate ?? DateTime.Now,
                c?.EndDate ?? DateTime.Now,
                e.AttendancePercent,
                e.TheoryScore,
                e.PracticeScore,
                e.FinalScore,
                e.EvaluationGrade,
                e.ResultStatus,
                e.IsCertificateIssued,
                e.CertificateNo
            );
        }).ToList();

        return new StaffTrainingProfileDto(
            staffCode,
            staffName,
            email,
            phone,
            dealerCode,
            dealerName,
            pos,
            activeCert != null,
            activeCert,
            certs,
            history
        );
    }

    public async Task<object> GetTrainingSummaryAsync(int? year, string? trainingType)
    {
        var qCourses = db.TrainingCourses.Where(c => c.OrgId == Org);
        var qEnr = db.TrainingEnrollments.Where(e => e.OrgId == Org);
        var qCert = db.StaffCertificates.Where(c => c.OrgId == Org);

        if (year.HasValue && year.Value > 0)
        {
            qCourses = qCourses.Where(c => c.StartDate.Year == year.Value);
            qCert = qCert.Where(c => c.IssueDate.Year == year.Value);
        }

        if (!string.IsNullOrWhiteSpace(trainingType))
        {
            var tt = trainingType.Trim();
            qCourses = qCourses.Where(c => c.TrainingType == tt);
            qCert = qCert.Where(c => c.CertificateType == tt);
        }

        var courses = await qCourses.ToListAsync();
        var enrollments = await qEnr.ToListAsync();
        var certificates = await qCert.ToListAsync();

        var totalCourses = courses.Count;
        var totalDraft = courses.Count(c => c.Status == "Draft");
        var totalScheduled = courses.Count(c => c.Status == "Scheduled");
        var totalInProgress = courses.Count(c => c.Status == "InProgress");
        var totalCompleted = courses.Count(c => c.Status == "Completed");
        var totalCancelled = courses.Count(c => c.Status == "Cancelled");

        var totalEnrollments = enrollments.Count;
        var totalPassed = enrollments.Count(e => e.ResultStatus == "Passed");
        var totalFailed = enrollments.Count(e => e.ResultStatus is "Failed" or "Dropped");
        var passRate = totalEnrollments > 0 ? Math.Round((decimal)totalPassed / totalEnrollments * 100, 1) : 0m;

        var totalCerts = certificates.Count;
        var totalActive = certificates.Count(c => c.Status == "Active" && c.ExpiryDate >= DateTime.Now);
        var totalExpired = certificates.Count(c => c.Status == "Expired" || (c.Status == "Active" && c.ExpiryDate < DateTime.Now));
        var totalRevoked = certificates.Count(c => c.Status == "Revoked");

        var byType = courses.GroupBy(c => c.TrainingType).Select(g =>
        {
            var cCodes = g.Select(x => x.TrainingCode).ToList();
            var cEnrs = enrollments.Where(e => cCodes.Contains(e.TrainingCode)).ToList();
            var pCount = cEnrs.Count(e => e.ResultStatus == "Passed");
            var enrCount = cEnrs.Count;
            var rate = enrCount > 0 ? Math.Round((decimal)pCount / enrCount * 100, 1) : 0m;
            return new TrainingCourseTypeStatsDto(
                g.Key,
                g.Count(),
                enrCount,
                pCount,
                rate
            );
        }).OrderByDescending(t => t.EnrolledCount).ToList();

        var byDealer = enrollments.GroupBy(e => e.DealerCode).Select(g =>
        {
            var dCerts = certificates.Where(c => c.DealerCode == g.Key).ToList();
            var activeCount = dCerts.Count(c => c.Status == "Active" && c.ExpiryDate >= DateTime.Now);
            var pCount = g.Count(e => e.ResultStatus == "Passed");
            var enrCount = g.Count();
            var stdRate = enrCount > 0 ? Math.Round((decimal)activeCount / enrCount * 100, 1) : 0m;
            return new TrainingDealerStatsDto(
                g.Key,
                g.First().DealerName ?? g.Key,
                enrCount,
                pCount,
                activeCount,
                stdRate
            );
        }).OrderBy(d => d.DealerCode).ToList();

        var byLevel = courses.GroupBy(c => c.Level).Select(g =>
        {
            var cCodes = g.Select(x => x.TrainingCode).ToList();
            var cEnrs = enrollments.Where(e => cCodes.Contains(e.TrainingCode)).ToList();
            return new TrainingLevelStatsDto(
                g.Key,
                g.Count(),
                cEnrs.Count,
                cEnrs.Count(e => e.ResultStatus == "Passed")
            );
        }).OrderBy(l => l.Level).ToList();

        return new TrainingSummaryDto(
            totalCourses,
            totalDraft,
            totalScheduled,
            totalInProgress,
            totalCompleted,
            totalCancelled,
            totalEnrollments,
            totalPassed,
            totalFailed,
            passRate,
            totalCerts,
            totalActive,
            totalExpired,
            totalRevoked,
            byType,
            byDealer,
            byLevel
        );
    }

    // ===== QUẢN LÝ GÓI DỊCH VỤ & THẺ BẢO DƯỠNG TRỌN GÓI XE Ô TÔ (BizCarSv.ServicePackage / Ser_ServicePackage) =====

    public async Task<object> CreateServicePackageAsync(CreateServicePackageDto dto)
    {
        if (string.IsNullOrWhiteSpace(dto.PackageName))
            throw new InvalidOperationException("Cần tên gói dịch vụ PackageName.");

        var now = DateTime.Now;
        var pkgType = string.IsNullOrWhiteSpace(dto.PackageType) ? "PeriodicMaintenance" : dto.PackageType.Trim();
        var model = string.IsNullOrWhiteSpace(dto.ApplicableModel) ? "ALL" : dto.ApplicableModel.Trim().ToUpperInvariant();
        var dealerCode = string.IsNullOrWhiteSpace(dto.DealerCode) ? "ALL" : dto.DealerCode.Trim().ToUpperInvariant();

        var packageNo = string.IsNullOrWhiteSpace(dto.PackageNo)
            ? $"PKG-{now:yyyy}-{(await db.ServicePackages.CountAsync(p => p.OrgId == Org) + 1):D4}"
            : dto.PackageNo.Trim().ToUpperInvariant();

        if (await db.ServicePackages.AnyAsync(p => p.OrgId == Org && p.PackageNo == packageNo))
            throw new InvalidOperationException($"Mã gói dịch vụ {packageNo} đã tồn tại trong hệ thống.");

        var package = new ServicePackage
        {
            OrgId = Org,
            PackageNo = packageNo,
            PackageNoUser = dto.PackageNoUser?.Trim() ?? $"GDV-{now:yyyy}/{packageNo}",
            PackageName = dto.PackageName.Trim(),
            DealerCode = dealerCode,
            DealerName = dto.DealerName?.Trim() ?? (dealerCode == "ALL" ? "Hyundai Toàn Quốc OEM" : dealerCode),
            PackageType = pkgType,
            ApplicableModel = model,
            MilestoneKm = dto.MilestoneKm ?? 5000,
            StandardTakingTimeMinutes = dto.StandardTakingTimeMinutes ?? 60,
            ValidityMonths = dto.ValidityMonths ?? 12,
            MaxUsageCount = dto.MaxUsageCount ?? 1,
            IsPublic = dto.IsPublic ?? true,
            IsUseBasePrice = dto.IsUseBasePrice ?? true,
            DiscountPercent = dto.DiscountPercent ?? 15m,
            Status = "Draft",
            Description = dto.Description?.Trim(),
            Remark = dto.Remark?.Trim(),
            CreatedBy = dto.CreatedBy?.Trim(),
            CreatedAt = now
        };

        decimal totalLabor = 0;
        decimal totalPart = 0;

        var laborLines = new List<ServicePackageLaborLine>();
        if (dto.LaborLines != null && dto.LaborLines.Count > 0)
        {
            int idx = 1;
            foreach (var item in dto.LaborLines)
            {
                if (string.IsNullOrWhiteSpace(item.ServiceItemCode) || string.IsNullOrWhiteSpace(item.ServiceItemName)) continue;
                var stdHours = item.StandardHours > 0 ? item.StandardHours : 0.5m;
                var price = item.LaborPrice >= 0 ? item.LaborPrice : 350000m;
                var disc = item.DiscountPercent ?? 0m;
                var amount = Math.Round(stdHours * price * (1 - disc / 100), 0);
                totalLabor += amount;

                laborLines.Add(new ServicePackageLaborLine
                {
                    OrgId = Org,
                    PackageNo = packageNo,
                    LineIndex = idx++,
                    ServiceItemCode = item.ServiceItemCode.Trim().ToUpperInvariant(),
                    ServiceItemName = item.ServiceItemName.Trim(),
                    StandardHours = stdHours,
                    LaborPrice = price,
                    DiscountPercent = disc,
                    LaborAmount = amount,
                    IsMandatory = item.IsMandatory ?? true,
                    Remark = item.Remark?.Trim()
                });
            }
        }

        var partLines = new List<ServicePackagePartLine>();
        if (dto.PartLines != null && dto.PartLines.Count > 0)
        {
            int idx = 1;
            foreach (var item in dto.PartLines)
            {
                if (string.IsNullOrWhiteSpace(item.PartCode) || string.IsNullOrWhiteSpace(item.PartName)) continue;
                var qty = item.Quantity > 0 ? item.Quantity : 1.0m;
                var price = item.UnitPrice >= 0 ? item.UnitPrice : 0m;
                var disc = item.DiscountPercent ?? 0m;
                var amount = Math.Round(qty * price * (1 - disc / 100), 0);
                totalPart += amount;

                partLines.Add(new ServicePackagePartLine
                {
                    OrgId = Org,
                    PackageNo = packageNo,
                    LineIndex = idx++,
                    PartCode = item.PartCode.Trim().ToUpperInvariant(),
                    PartName = item.PartName.Trim(),
                    Unit = string.IsNullOrWhiteSpace(item.Unit) ? "Cái" : item.Unit.Trim(),
                    Quantity = qty,
                    UnitPrice = price,
                    DiscountPercent = disc,
                    PartAmount = amount,
                    IsMandatory = item.IsMandatory ?? true,
                    Remark = item.Remark?.Trim()
                });
            }
        }

        package.TotalLaborAmount = totalLabor;
        package.TotalPartAmount = totalPart;
        package.OriginalPrice = totalLabor + totalPart;
        package.PackagePrice = dto.PackagePrice.HasValue && dto.PackagePrice.Value > 0
            ? dto.PackagePrice.Value
            : Math.Round(package.OriginalPrice * (1 - package.DiscountPercent / 100), 0);

        db.ServicePackages.Add(package);
        await db.SaveChangesAsync();

        foreach (var l in laborLines) l.ServicePackageId = package.Id;
        foreach (var p in partLines) p.ServicePackageId = package.Id;

        if (laborLines.Count > 0) db.ServicePackageLaborLines.AddRange(laborLines);
        if (partLines.Count > 0) db.ServicePackagePartLines.AddRange(partLines);
        if (laborLines.Count > 0 || partLines.Count > 0) await db.SaveChangesAsync();

        return new
        {
            package,
            laborLines,
            partLines
        };
    }

    public async Task<object> ListServicePackagesAsync(string? status, string? dealer, string? packageType, string? model, string? packageNo)
    {
        var q = db.ServicePackages.Where(p => p.OrgId == Org);

        if (!string.IsNullOrWhiteSpace(status))
            q = q.Where(p => p.Status == status.Trim());

        if (!string.IsNullOrWhiteSpace(dealer))
        {
            var d = dealer.Trim().ToUpperInvariant();
            q = q.Where(p => p.DealerCode == d || p.DealerCode == "ALL");
        }

        if (!string.IsNullOrWhiteSpace(packageType))
            q = q.Where(p => p.PackageType == packageType.Trim());

        if (!string.IsNullOrWhiteSpace(model))
        {
            var m = model.Trim().ToUpperInvariant();
            q = q.Where(p => p.ApplicableModel == m || p.ApplicableModel == "ALL");
        }

        if (!string.IsNullOrWhiteSpace(packageNo))
        {
            var no = packageNo.Trim().ToUpperInvariant();
            q = q.Where(p => p.PackageNo.Contains(no) || (p.PackageNoUser != null && p.PackageNoUser.Contains(no)) || p.PackageName.Contains(packageNo.Trim()));
        }

        var items = await q.OrderByDescending(p => p.CreatedAt).ToListAsync();
        return new { count = items.Count, items };
    }

    public async Task<object?> GetServicePackageAsync(string packageNo)
    {
        packageNo = packageNo.Trim().ToUpperInvariant();
        var package = await db.ServicePackages.FirstOrDefaultAsync(p => p.OrgId == Org && (p.PackageNo == packageNo || p.PackageNoUser == packageNo));
        if (package is null) return null;

        var laborLines = await db.ServicePackageLaborLines.Where(l => l.OrgId == Org && l.ServicePackageId == package.Id).OrderBy(l => l.LineIndex).ToListAsync();
        var partLines = await db.ServicePackagePartLines.Where(p => p.OrgId == Org && p.ServicePackageId == package.Id).OrderBy(p => p.LineIndex).ToListAsync();
        var recentSubscriptions = await db.ServicePackageSubscriptions.Where(s => s.OrgId == Org && s.PackageNo == package.PackageNo).OrderByDescending(s => s.CreatedAt).Take(10).ToListAsync();

        return new
        {
            package,
            laborLines,
            partLines,
            recentSubscriptions
        };
    }

    public async Task<object?> UpdateServicePackageHeaderAsync(string packageNo, UpdateServicePackageHeaderDto dto)
    {
        packageNo = packageNo.Trim().ToUpperInvariant();
        var package = await db.ServicePackages.FirstOrDefaultAsync(p => p.OrgId == Org && (p.PackageNo == packageNo || p.PackageNoUser == packageNo));
        if (package is null) return null;

        if (dto.PackageNoUser != null) package.PackageNoUser = dto.PackageNoUser.Trim();
        if (!string.IsNullOrWhiteSpace(dto.PackageName)) package.PackageName = dto.PackageName.Trim();
        if (!string.IsNullOrWhiteSpace(dto.DealerCode)) package.DealerCode = dto.DealerCode.Trim().ToUpperInvariant();
        if (dto.DealerName != null) package.DealerName = dto.DealerName.Trim();
        if (!string.IsNullOrWhiteSpace(dto.PackageType)) package.PackageType = dto.PackageType.Trim();
        if (!string.IsNullOrWhiteSpace(dto.ApplicableModel)) package.ApplicableModel = dto.ApplicableModel.Trim().ToUpperInvariant();
        if (dto.MilestoneKm.HasValue) package.MilestoneKm = dto.MilestoneKm.Value;
        if (dto.StandardTakingTimeMinutes.HasValue) package.StandardTakingTimeMinutes = dto.StandardTakingTimeMinutes.Value;
        if (dto.ValidityMonths.HasValue) package.ValidityMonths = dto.ValidityMonths.Value;
        if (dto.MaxUsageCount.HasValue) package.MaxUsageCount = dto.MaxUsageCount.Value;
        if (dto.IsPublic.HasValue) package.IsPublic = dto.IsPublic.Value;
        if (dto.IsUseBasePrice.HasValue) package.IsUseBasePrice = dto.IsUseBasePrice.Value;
        if (dto.DiscountPercent.HasValue)
        {
            package.DiscountPercent = dto.DiscountPercent.Value;
            if (!dto.PackagePrice.HasValue)
                package.PackagePrice = Math.Round(package.OriginalPrice * (1 - package.DiscountPercent / 100), 0);
        }
        if (dto.PackagePrice.HasValue) package.PackagePrice = dto.PackagePrice.Value;
        if (dto.Description != null) package.Description = dto.Description.Trim();
        if (dto.Remark != null) package.Remark = dto.Remark.Trim();

        await db.SaveChangesAsync();
        return package;
    }

    public async Task<object?> ServicePackageTransitionAsync(string packageNo, string action, ServicePackageTransitionDto? dto)
    {
        packageNo = packageNo.Trim().ToUpperInvariant();
        var package = await db.ServicePackages.FirstOrDefaultAsync(p => p.OrgId == Org && (p.PackageNo == packageNo || p.PackageNoUser == packageNo));
        if (package is null) return null;

        var now = DateTime.Now;
        var act = action.Trim().ToLowerInvariant();

        switch (act)
        {
            case "approve" or "activate" or "active":
                package.Status = "Active";
                package.ApprovedBy = dto?.Actor?.Trim() ?? "ServiceManager";
                package.ApprovedAt = dto?.TransitionDate ?? now;
                break;

            case "suspend":
                package.Status = "Suspended";
                break;

            case "resume" or "reactivate":
                package.Status = "Active";
                break;

            case "archive":
                package.Status = "Archived";
                package.ArchivedBy = dto?.Actor?.Trim() ?? "ServiceManager";
                package.ArchivedAt = dto?.TransitionDate ?? now;
                break;

            case "draft":
                package.Status = "Draft";
                break;

            default:
                throw new InvalidOperationException($"Hành động {action} không hợp lệ cho gói dịch vụ.");
        }

        if (dto?.Note != null) package.Remark = (package.Remark + " | " + dto.Note).Trim(' ', '|');
        await db.SaveChangesAsync();

        return package;
    }

    public async Task<object?> AddServicePackageLaborLinesAsync(string packageNo, List<ServicePackageLaborLineInputDto> items)
    {
        packageNo = packageNo.Trim().ToUpperInvariant();
        var package = await db.ServicePackages.FirstOrDefaultAsync(p => p.OrgId == Org && (p.PackageNo == packageNo || p.PackageNoUser == packageNo));
        if (package is null) return null;

        var currentMaxIndex = await db.ServicePackageLaborLines.Where(l => l.OrgId == Org && l.ServicePackageId == package.Id).MaxAsync(l => (int?)l.LineIndex) ?? 0;

        var newLines = new List<ServicePackageLaborLine>();
        foreach (var item in items)
        {
            if (string.IsNullOrWhiteSpace(item.ServiceItemCode) || string.IsNullOrWhiteSpace(item.ServiceItemName)) continue;
            var stdHours = item.StandardHours > 0 ? item.StandardHours : 0.5m;
            var price = item.LaborPrice >= 0 ? item.LaborPrice : 350000m;
            var disc = item.DiscountPercent ?? 0m;
            var amount = Math.Round(stdHours * price * (1 - disc / 100), 0);

            newLines.Add(new ServicePackageLaborLine
            {
                OrgId = Org,
                ServicePackageId = package.Id,
                PackageNo = package.PackageNo,
                LineIndex = ++currentMaxIndex,
                ServiceItemCode = item.ServiceItemCode.Trim().ToUpperInvariant(),
                ServiceItemName = item.ServiceItemName.Trim(),
                StandardHours = stdHours,
                LaborPrice = price,
                DiscountPercent = disc,
                LaborAmount = amount,
                IsMandatory = item.IsMandatory ?? true,
                Remark = item.Remark?.Trim()
            });
        }

        if (newLines.Count > 0)
        {
            db.ServicePackageLaborLines.AddRange(newLines);
            await db.SaveChangesAsync();

            package.TotalLaborAmount = await db.ServicePackageLaborLines.Where(l => l.OrgId == Org && l.ServicePackageId == package.Id).SumAsync(l => l.LaborAmount);
            package.OriginalPrice = package.TotalLaborAmount + package.TotalPartAmount;
            package.PackagePrice = Math.Round(package.OriginalPrice * (1 - package.DiscountPercent / 100), 0);
            await db.SaveChangesAsync();
        }

        return await GetServicePackageAsync(package.PackageNo);
