        if (!string.IsNullOrWhiteSpace(dto.KPICategory)) indicator.KPICategory = dto.KPICategory.Trim();
        if (!string.IsNullOrWhiteSpace(dto.Unit)) indicator.Unit = dto.Unit.Trim();
