        return new VehicleSalesKpiInfoDto(
            veh.Vin,
            veh.Model,
            veh.EngineNo,
            veh.Color,
            veh.StorageCode,
            veh.DealerCode,
            veh.LastSalesKpiNo,
            veh.LastSalesKpiDate,
            veh.SalesKpiCount,
            targetKpi,
            relatedLogs
        );
    }

