            l.SpecCode,
            l.ModelCode,
            l.ColorCode,
            l.ProductionMonth,
            l.EngineNo,
            l.PDIDtlStatus,
            l.PDIStorageStatus,
            l.PdiResult,
            l.FlagRepair,
            l.RepairRemark,
            l.PDIDate,
            l.Remark,
            l.ApprovedBy,
            l.ApprovedAt,
            vehicle = vehicles.TryGetValue(l.VIN, out var v) ? new { v.Model, v.Color, v.EngineNo, status = v.Status.ToString(), v.StorageCode } : null
        }).ToList();

        return new
