            vehicle = vehicles.TryGetValue(l.Vin, out var v) ? new { v.Model, v.Color, v.EngineNo, status = v.Status.ToString(), currentStorage = v.StorageCode, v.DealerCode } : null
        }).ToList();

        return new
        {
            req.SRTReqNo,
            req.TransporterCode,
            req.TransportContractNo,
            req.TruckPlateNo,
            req.DriverName,
            req.DriverPhone,
            req.FromStorage,
            req.ToStorage,
            req.EstimatedDeparture,
            req.EstimatedArrival,
            req.Status,
            req.Remark,
            req.CreatedBy,
            req.CreatedAt,
            req.ApprovedBy,
            req.ApprovedAt,
            req.RejectBy,
            req.RejectAt,
            vins = details
        };
    }

    public async Task<object?> RearrangeTransportRequestTransitionAsync(string srtReqNo, string action, RearrangeTransportRequestTransitionDto? dto)
    {
        srtReqNo = srtReqNo.Trim().ToUpperInvariant();
        var req = await db.RearrangeTransportRequests.FirstOrDefaultAsync(r => r.OrgId == Org && r.SRTReqNo == srtReqNo);
        if (req is null) return null;

        var now = DateTime.Now;
        var lines = await db.RearrangeTransportRequestLines.Where(l => l.OrgId == Org && l.RearrangeTransportRequestId == req.Id).ToListAsync();

        switch (action.ToLowerInvariant())
        {
            case "approve":
                if (req.Status != "P") return null;
                req.Status = "A";
                req.ApprovedBy = dto?.By;
                req.ApprovedAt = now;
                foreach (var l in lines) if (l.Status == "P") l.Status = "A";
                foreach (var l in lines) Log(l.Vin, "RearrangeTransportApproved", srtReqNo);
                break;

            case "reject":
                if (req.Status != "P") return null;
                req.Status = "R";
                req.RejectBy = dto?.By;
                req.RejectAt = now;
                if (!string.IsNullOrWhiteSpace(dto?.Note))
                    req.Remark = string.IsNullOrWhiteSpace(req.Remark) ? dto.Note : $"{req.Remark} | Từ chối: {dto.Note}";
                foreach (var l in lines) l.Status = "R";
                foreach (var l in lines) Log(l.Vin, "RearrangeTransportRejected", $"{srtReqNo} Lý do: {dto?.Note ?? "N/A"}");
                break;

            default:
                return null;
        }

        await db.SaveChangesAsync();
        return new { req.SRTReqNo, status = req.Status, req.ApprovedAt, req.RejectAt };
    }

    public async Task<object?> RemoveRearrangeTransportRequestLineAsync(string srtReqNo, string vin)
    {
        srtReqNo = srtReqNo.Trim().ToUpperInvariant();
        vin = vin.Trim().ToUpperInvariant();

        var req = await db.RearrangeTransportRequests.FirstOrDefaultAsync(r => r.OrgId == Org && r.SRTReqNo == srtReqNo);
        if (req is null || req.Status != "P") return null;

        var line = await db.RearrangeTransportRequestLines.FirstOrDefaultAsync(l => l.OrgId == Org && l.RearrangeTransportRequestId == req.Id && l.Vin == vin);
        if (line is null) return null;

        db.RearrangeTransportRequestLines.Remove(line);
        Log(vin, "RearrangeTransportLineRemoved", srtReqNo);
        await db.SaveChangesAsync();

        var remaining = await db.RearrangeTransportRequestLines.CountAsync(l => l.OrgId == Org && l.RearrangeTransportRequestId == req.Id);
        return new { req.SRTReqNo, removedVin = vin, remainingVins = remaining };
    }

    public async Task<object?> GetVehicleRearrangeTransportRequestInfoAsync(string vin)
    {
        vin = vin.Trim().ToUpperInvariant();
        var vehicle = await db.Vehicles.FirstOrDefaultAsync(v => v.OrgId == Org && v.Vin == vin);
        if (vehicle is null) return null;

        var reqNos = await db.RearrangeTransportRequestLines
            .Where(l => l.OrgId == Org && l.Vin == vin)
            .Select(l => l.SRTReqNo).Distinct().ToListAsync();

        var requests = await db.RearrangeTransportRequests
            .Where(r => r.OrgId == Org && reqNos.Contains(r.SRTReqNo))
            .OrderByDescending(r => r.Id).ToListAsync();

        return new
        {
            vehicle.Vin,
            vehicle.Model,
            status = vehicle.Status.ToString(),
            requests = requests.Select(r => new
            {
                r.SRTReqNo,
                r.TransporterCode,
                r.TransportContractNo,
                r.TruckPlateNo,
                r.FromStorage,
                r.ToStorage,
                r.Status,
                r.CreatedAt,
                r.ApprovedAt
            }).ToList()
        };
    }

    // ===== Kế hoạch xe về / Kế hoạch nhập xe theo đại lý (BizHTC.Car.Car_Plan / CarPlan) =====
    public async Task<object> CreateCarPlanAsync(CreateCarPlanDto dto)
    {
        if (string.IsNullOrWhiteSpace(dto.DealerCode))
            throw new InvalidOperationException("Cần DealerCode để tạo kế hoạch xe về.");
        if (dto.Items is null || dto.Items.Count == 0)
            throw new InvalidOperationException("Cần ít nhất 1 dòng chi tiết xe trong kế hoạch.");

        foreach (var item in dto.Items)
        {
            if (string.IsNullOrWhiteSpace(item.Model))
                throw new InvalidOperationException("Mỗi dòng kế hoạch phải có Model xe.");
            if (item.QtyOrder <= 0)
                throw new InvalidOperationException("Số lượng đặt QtyOrder phải lớn hơn 0.");
        }

        var cpCode = string.IsNullOrWhiteSpace(dto.CPCode)
            ? "CP" + DateTime.Now.ToString("yyMMddHHmmss")
            : dto.CPCode!.Trim().ToUpperInvariant();

        if (await db.CarPlans.AnyAsync(c => c.OrgId == Org && c.CPCode == cpCode))
            throw new InvalidOperationException($"Mã kế hoạch xe về {cpCode} đã tồn tại.");

        var plan = new CarPlan
        {
            OrgId = Org,
            CPCode = cpCode,
            DealerCode = dto.DealerCode.Trim(),
            OrderNo = dto.OrderNo?.Trim(),
            PlanMonth = dto.PlanMonth?.Trim() ?? DateTime.Now.ToString("yyyy-MM"),
            TotalQtyOrder = dto.Items.Sum(i => i.QtyOrder),
            TotalQty = 0,
            TotalArrivedQty = 0,
            TotalPendingQty = 0,
            Status = "Draft",
            CreatedBy = dto.CreatedBy?.Trim(),
            Remark = dto.Remark?.Trim(),
            CreatedAt = DateTime.Now
        };
        db.CarPlans.Add(plan);
        await db.SaveChangesAsync();

        foreach (var item in dto.Items)
        {
            db.CarPlanLines.Add(new CarPlanLine
            {
                OrgId = Org,
                CarPlanId = plan.Id,
                CPCode = cpCode,
                Model = item.Model.Trim(),
                SpecCode = item.SpecCode?.Trim(),
                Color = item.Color?.Trim(),
                QtyOrder = item.QtyOrder,
                Qty = item.Qty ?? 0,
                ArrivedQty = 0,
                PendingQty = 0,
                Status = "Pending",
                Remark = item.Remark?.Trim()
            });
        }
        await db.SaveChangesAsync();

        return new
        {
            plan.CPCode,
            plan.DealerCode,
            plan.OrderNo,
            plan.PlanMonth,
            plan.TotalQtyOrder,
            status = plan.Status,
            linesCount = dto.Items.Count
        };
    }

    public async Task<object> ListCarPlansAsync(string? status, string? dealer, string? orderNo, string? model, string? planMonth)
    {
        var q = db.CarPlans.Where(c => c.OrgId == Org);
        if (!string.IsNullOrWhiteSpace(status)) q = q.Where(c => c.Status == status);
        if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(c => c.DealerCode == dealer);
        if (!string.IsNullOrWhiteSpace(orderNo)) q = q.Where(c => c.OrderNo != null && c.OrderNo.Contains(orderNo));
        if (!string.IsNullOrWhiteSpace(planMonth)) q = q.Where(c => c.PlanMonth == planMonth);
        if (!string.IsNullOrWhiteSpace(model))
        {
            var m = model.Trim();
            var matchedCodes = await db.CarPlanLines
                .Where(l => l.OrgId == Org && l.Model.Contains(m))
                .Select(l => l.CPCode)
                .Distinct()
                .ToListAsync();
            q = q.Where(c => matchedCodes.Contains(c.CPCode));
        }

        var items = await q.OrderByDescending(c => c.Id).Take(500).Select(c => new
        {
            c.CPCode,
            c.DealerCode,
            c.OrderNo,
            c.PlanMonth,
            c.TotalQtyOrder,
            c.TotalQty,
            c.TotalArrivedQty,
            c.TotalPendingQty,
            c.Status,
            c.CreatedBy,
            c.ApprovedBy,
            c.ApprovedAt,
            c.CreatedAt,
            linesCount = db.CarPlanLines.Count(l => l.OrgId == Org && l.CarPlanId == c.Id)
        }).ToListAsync();

        return new { count = items.Count, items };
    }

    public async Task<object?> GetCarPlanAsync(string cpCode)
    {
        cpCode = cpCode.Trim().ToUpperInvariant();
        var plan = await db.CarPlans.FirstOrDefaultAsync(c => c.OrgId == Org && c.CPCode == cpCode);
        if (plan is null) return null;

        var lines = await db.CarPlanLines.Where(l => l.OrgId == Org && l.CarPlanId == plan.Id).ToListAsync();

        return new
        {
            plan.CPCode,
            plan.DealerCode,
            plan.OrderNo,
            plan.PlanMonth,
            plan.TotalQtyOrder,
            plan.TotalQty,
            plan.TotalArrivedQty,
            plan.TotalPendingQty,
            plan.Status,
            plan.CreatedBy,
            plan.ApprovedBy,
            plan.ApprovedAt,
            plan.CompletedAt,
            plan.Remark,
            plan.CreatedAt,
            lines = lines.Select(l => new
            {
                l.Id,
                l.Model,
                l.SpecCode,
                l.Color,
                l.QtyOrder,
                l.Qty,
                l.ArrivedQty,
                l.PendingQty,
                l.Status,
                l.Remark
            }).ToList()
        };
    }

    public async Task<object?> CarPlanTransitionAsync(string cpCode, string action, CarPlanTransitionDto? dto)
    {
        cpCode = cpCode.Trim().ToUpperInvariant();
        var plan = await db.CarPlans.FirstOrDefaultAsync(c => c.OrgId == Org && c.CPCode == cpCode);
        if (plan is null) return null;

        var now = DateTime.Now;
        var lines = await db.CarPlanLines.Where(l => l.OrgId == Org && l.CarPlanId == plan.Id).ToListAsync();

        switch (action.ToLowerInvariant())
        {
            case "submit":
                if (plan.Status != "Draft") return null;
                plan.Status = "Submitted";
                break;

            case "approve":
                if (plan.Status is not ("Draft" or "Submitted")) return null;
                // Duyệt số lượng từng dòng (mặc định = số lượng đặt nếu không chỉ định).
                foreach (var line in lines)
                {
                    var approve = dto?.Items?.FirstOrDefault(i =>
                        (i.LineId.HasValue && i.LineId.Value == line.Id) ||
                        (!i.LineId.HasValue && i.Model == line.Model && i.SpecCode == line.SpecCode && i.Color == line.Color));
                    line.Qty = approve?.Qty ?? line.QtyOrder;
                    line.PendingQty = line.Qty - line.ArrivedQty;
                    line.Status = "Approved";
                }
                plan.TotalQty = lines.Sum(l => l.Qty);
                plan.TotalPendingQty = lines.Sum(l => l.PendingQty);
                plan.Status = "Approved";
                plan.ApprovedBy = dto?.ApprovedBy?.Trim();
                plan.ApprovedAt = now;
                break;

            case "complete":
                if (plan.Status != "Approved") return null;
                plan.Status = "Completed";
                plan.CompletedAt = now;
                break;

            case "reject":
                if (plan.Status is "Completed" or "Rejected" or "Cancelled") return null;
                plan.Status = "Rejected";
                foreach (var line in lines) line.Status = "Rejected";
                break;

            case "cancel":
                if (plan.Status is "Completed" or "Rejected" or "Cancelled") return null;
                plan.Status = "Cancelled";
                foreach (var line in lines) line.Status = "Cancelled";
                break;

            default:
                return null;
        }

        await db.SaveChangesAsync();
        return new { plan.CPCode, status = plan.Status, plan.TotalQty, plan.TotalArrivedQty, plan.TotalPendingQty };
    }

    // Ghi nhận 1 xe VIN đã về kho theo kế hoạch: tăng ArrivedQty của dòng khớp model/spec/màu, cập nhật tổng.
    public async Task<object?> RecordCarPlanArrivalAsync(string cpCode, CarPlanArrivalDto dto)
    {
        cpCode = cpCode.Trim().ToUpperInvariant();
        var plan = await db.CarPlans.FirstOrDefaultAsync(c => c.OrgId == Org && c.CPCode == cpCode);
        if (plan is null) return null;
        if (plan.Status is not ("Approved" or "Completed")) return null;
        if (string.IsNullOrWhiteSpace(dto.Vin)) throw new InvalidOperationException("Cần Vin của xe về.");

        var lines = await db.CarPlanLines.Where(l => l.OrgId == Org && l.CarPlanId == plan.Id).ToListAsync();
        var line = lines.FirstOrDefault(l =>
            (dto.Model is not null && l.Model == dto.Model) &&
            (dto.SpecCode is null || l.SpecCode == dto.SpecCode) &&
            (dto.Color is null || l.Color == dto.Color))
            ?? lines.FirstOrDefault(l => dto.Model is not null && l.Model == dto.Model);
        if (line is null) return null;

        line.ArrivedQty += 1;
        line.PendingQty = Math.Max(0, line.Qty - line.ArrivedQty);
        if (line.PendingQty == 0) line.Status = "Arrived";

        plan.TotalArrivedQty = lines.Sum(l => l.ArrivedQty);
        plan.TotalPendingQty = lines.Sum(l => l.PendingQty);
        if (plan.TotalPendingQty == 0 && plan.Status == "Approved") plan.Status = "Completed";

        await db.SaveChangesAsync();
        return new { plan.CPCode, line.Model, line.ArrivedQty, line.PendingQty, status = plan.Status };
    }

    public async Task<object> GetCarPlanSummaryAsync(string? dealerCode, string? planMonth)
    {
        var q = db.CarPlans.Where(c => c.OrgId == Org);
        if (!string.IsNullOrWhiteSpace(dealerCode)) q = q.Where(c => c.DealerCode == dealerCode);
        if (!string.IsNullOrWhiteSpace(planMonth)) q = q.Where(c => c.PlanMonth == planMonth);

        var plans = await q.ToListAsync();
        var byStatus = plans.GroupBy(c => c.Status)
            .Select(g => new { status = g.Key, count = g.Count() })
            .OrderByDescending(x => x.count)
            .ToList();

        return new
        {
            totalPlans = plans.Count,
            totalQtyOrder = plans.Sum(c => c.TotalQtyOrder),
            totalQty = plans.Sum(c => c.TotalQty),
            totalArrivedQty = plans.Sum(c => c.TotalArrivedQty),
            totalPendingQty = plans.Sum(c => c.TotalPendingQty),
            byStatus
        };
    }

    // ===== Danh mục kho bãi OEM & Đại lý (BizHTC.DMS40.Mst_StorageGlobal / Dlr_StorageLocal) =====
    // Mst_StorageGlobal: kho/bãi toàn cục của Hãng OEM, khóa nghiệp vụ = (StorageCode, ModelCode).
    public async Task<object> CreateStorageGlobalAsync(CreateStorageGlobalDto dto)
    {
        var storageCode = dto.StorageCode?.Trim().ToUpperInvariant();
        var modelCode = dto.ModelCode?.Trim().ToUpperInvariant();
        if (string.IsNullOrWhiteSpace(storageCode))
            throw new InvalidOperationException("Cần mã vị trí kho StorageCode.");
        if (string.IsNullOrWhiteSpace(modelCode))
            throw new InvalidOperationException("Cần mã dòng xe ModelCode.");

        if (await db.StorageGlobals.AnyAsync(s => s.OrgId == Org && s.StorageCode == storageCode && s.ModelCode == modelCode))
            throw new InvalidOperationException($"Vị trí kho {storageCode} cho dòng xe {modelCode} đã tồn tại.");

        var entity = new StorageGlobal
        {
            OrgId = Org,
            StorageCode = storageCode,
            ModelCode = modelCode,
            FlagActive = true,
            CreatedAt = DateTime.Now,
            LogLUDateTime = DateTime.Now
        };
        db.StorageGlobals.Add(entity);
        await db.SaveChangesAsync();
        return new { entity.Id, entity.StorageCode, entity.ModelCode, entity.FlagActive };
    }

    public async Task<object> ListStorageGlobalsAsync(string? storageCode, string? modelCode, bool? activeOnly)
    {
        var q = db.StorageGlobals.Where(s => s.OrgId == Org);
        if (!string.IsNullOrWhiteSpace(storageCode))
        {
            var sc = storageCode.Trim().ToUpperInvariant();
            q = q.Where(s => s.StorageCode.Contains(sc));
        }
        if (!string.IsNullOrWhiteSpace(modelCode))
        {
            var mc = modelCode.Trim().ToUpperInvariant();
            q = q.Where(s => s.ModelCode.Contains(mc));
        }
        if (activeOnly == true) q = q.Where(s => s.FlagActive);

        var items = await q.OrderBy(s => s.StorageCode).ThenBy(s => s.ModelCode)
            .Select(s => new { s.Id, s.StorageCode, s.ModelCode, s.FlagActive, s.CreatedAt, s.LogLUDateTime, s.LogLUBy })
            .ToListAsync();
        return new { count = items.Count, items };
    }

    public async Task<object?> GetStorageGlobalAsync(string storageCode, string modelCode)
    {
        var sc = storageCode.Trim().ToUpperInvariant();
        var mc = modelCode.Trim().ToUpperInvariant();
        var s = await db.StorageGlobals.FirstOrDefaultAsync(x => x.OrgId == Org && x.StorageCode == sc && x.ModelCode == mc);
        if (s is null) return null;
        return new { s.Id, s.StorageCode, s.ModelCode, s.FlagActive, s.CreatedAt, s.LogLUDateTime, s.LogLUBy };
    }

    public async Task<object?> UpdateStorageGlobalAsync(string storageCode, string modelCode, UpdateStorageGlobalDto dto)
    {
        var sc = storageCode.Trim().ToUpperInvariant();
        var mc = modelCode.Trim().ToUpperInvariant();
        var s = await db.StorageGlobals.FirstOrDefaultAsync(x => x.OrgId == Org && x.StorageCode == sc && x.ModelCode == mc);
        if (s is null) return null;

        if (dto.FlagActive.HasValue) s.FlagActive = dto.FlagActive.Value;
        s.LogLUDateTime = DateTime.Now;
        s.LogLUBy = dto.By?.Trim();
        await db.SaveChangesAsync();
        return new { s.StorageCode, s.ModelCode, s.FlagActive, s.LogLUDateTime, s.LogLUBy };
    }

    public async Task<object?> DeleteStorageGlobalAsync(string storageCode, string modelCode)
    {
        var sc = storageCode.Trim().ToUpperInvariant();
        var mc = modelCode.Trim().ToUpperInvariant();
        var s = await db.StorageGlobals.FirstOrDefaultAsync(x => x.OrgId == Org && x.StorageCode == sc && x.ModelCode == mc);
        if (s is null) return null;
        db.StorageGlobals.Remove(s);
        await db.SaveChangesAsync();
        return new { deleted = true, s.StorageCode, s.ModelCode };
    }

    // ===== Danh mục Giá xe tồn kho theo phiên bản (BizHTC.DMS40.Mst_CarPriceInStock) =====
    // Mst_CarPriceInStock: giá nhập/giá tồn kho theo phiên bản xe, khóa nghiệp vụ = (SpecCode, EffectiveDate).
    public async Task<object> CreateCarPriceInStockAsync(CreateCarPriceInStockDto dto)
    {
        var specCode = dto.SpecCode?.Trim().ToUpperInvariant();
        if (string.IsNullOrWhiteSpace(specCode))
            throw new InvalidOperationException("Cần mã phiên bản xe SpecCode.");
        if (dto.UnitPriceIn < 0)
            throw new InvalidOperationException("Đơn giá tồn kho UnitPriceIn phải >= 0.");
        if (dto.EffectiveDate.Date < DateTime.Now.Date)
            throw new InvalidOperationException("Ngày hiệu lực EffectiveDate không được ở quá khứ.");

        if (await db.CarPriceInStocks.AnyAsync(p => p.OrgId == Org && p.SpecCode == specCode && p.EffectiveDate == dto.EffectiveDate.Date))
            throw new InvalidOperationException($"Giá tồn kho cho phiên bản {specCode} ngày {dto.EffectiveDate:yyyy-MM-dd} đã tồn tại.");

        var entity = new CarPriceInStock
        {
            OrgId = Org,
            SpecCode = specCode,
            EffectiveDate = dto.EffectiveDate.Date,
            UnitPriceIn = dto.UnitPriceIn,
            CreatedAt = DateTime.Now,
            CreatedBy = dto.CreatedBy?.Trim(),
            LogLUDateTime = DateTime.Now,
            LogLUBy = dto.CreatedBy?.Trim()
        };
        db.CarPriceInStocks.Add(entity);
        await db.SaveChangesAsync();
        return new { entity.Id, entity.SpecCode, entity.EffectiveDate, entity.UnitPriceIn };
    }

    public async Task<object> ListCarPriceInStocksAsync(string? specCode, DateTime? fromDate, DateTime? toDate)
    {
        var q = db.CarPriceInStocks.Where(p => p.OrgId == Org);
        if (!string.IsNullOrWhiteSpace(specCode))
        {
            var sc = specCode.Trim().ToUpperInvariant();
            q = q.Where(p => p.SpecCode.Contains(sc));
        }
        if (fromDate.HasValue) q = q.Where(p => p.EffectiveDate >= fromDate.Value.Date);
        if (toDate.HasValue) q = q.Where(p => p.EffectiveDate <= toDate.Value.Date);

        var items = await q.OrderBy(p => p.SpecCode).ThenByDescending(p => p.EffectiveDate)
            .Select(p => new { p.Id, p.SpecCode, p.EffectiveDate, p.UnitPriceIn, p.CreatedAt, p.CreatedBy, p.LogLUDateTime, p.LogLUBy })
            .ToListAsync();
        return new { count = items.Count, items };
    }

    public async Task<object?> GetCarPriceInStockAsync(string specCode, DateTime effectiveDate)
    {
        var sc = specCode.Trim().ToUpperInvariant();
        var ed = effectiveDate.Date;
        var p = await db.CarPriceInStocks.FirstOrDefaultAsync(x => x.OrgId == Org && x.SpecCode == sc && x.EffectiveDate == ed);
        if (p is null) return null;
        return new { p.Id, p.SpecCode, p.EffectiveDate, p.UnitPriceIn, p.CreatedAt, p.CreatedBy, p.LogLUDateTime, p.LogLUBy };
    }

    public async Task<object?> UpdateCarPriceInStockAsync(string specCode, DateTime effectiveDate, UpdateCarPriceInStockDto dto)
    {
        var sc = specCode.Trim().ToUpperInvariant();
        var ed = effectiveDate.Date;
        var p = await db.CarPriceInStocks.FirstOrDefaultAsync(x => x.OrgId == Org && x.SpecCode == sc && x.EffectiveDate == ed);
        if (p is null) return null;

        if (dto.UnitPriceIn.HasValue)
        {
            if (dto.UnitPriceIn.Value < 0)
                throw new InvalidOperationException("Đơn giá tồn kho UnitPriceIn phải >= 0.");
            p.UnitPriceIn = dto.UnitPriceIn.Value;
        }
        if (dto.EffectiveDate.HasValue)
        {
            var newDate = dto.EffectiveDate.Value.Date;
            if (newDate != p.EffectiveDate && await db.CarPriceInStocks.AnyAsync(x => x.OrgId == Org && x.SpecCode == sc && x.EffectiveDate == newDate))
                throw new InvalidOperationException($"Giá tồn kho cho phiên bản {sc} ngày {newDate:yyyy-MM-dd} đã tồn tại.");
            p.EffectiveDate = newDate;
        }
        p.LogLUDateTime = DateTime.Now;
        p.LogLUBy = dto.By?.Trim();
        await db.SaveChangesAsync();
        return new { p.SpecCode, p.EffectiveDate, p.UnitPriceIn, p.LogLUDateTime, p.LogLUBy };
    }

    public async Task<object?> DeleteCarPriceInStockAsync(string specCode, DateTime effectiveDate)
    {
        var sc = specCode.Trim().ToUpperInvariant();
        var ed = effectiveDate.Date;
        var p = await db.CarPriceInStocks.FirstOrDefaultAsync(x => x.OrgId == Org && x.SpecCode == sc && x.EffectiveDate == ed);
        if (p is null) return null;
        db.CarPriceInStocks.Remove(p);
        await db.SaveChangesAsync();
        return new { deleted = true, p.SpecCode, p.EffectiveDate };
    }

