            l.ColorCode,
            l.EngineNoInit,
            l.EngineNo,
            l.VinYear,
            l.ShopCCCode,
            l.StationCCCode,
            l.ConvertRuleCode,
            l.WOStatusDtl,
            l.VinStatus,
            l.VinShopStatus,
            l.WkDTime,
            l.WkBy,
            l.FinishDTime,
            l.FinishBy,
            l.EffDTimeStart_BS,
            l.EffDTimeEnd_BS,
            l.EffDTimeStart_PS,
            l.EffDTimeEnd_PS,
